  { name: 'น้ำมันเครื่อง', parent: 'สินค้า', products: 19, state: 'ใช้งาน', color: 'amber' },
  { name: 'อะไหล่และอุปกรณ์', parent: 'สินค้า', products: 31, state: 'ใช้งาน', color: 'blue' },
